create extension if not exists pgcrypto;
create table if not exists public.site_content(content_key text primary key,content_value jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now());
create table if not exists public.portfolio_projects(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,type text not null default '',summary text not null default '',meta text not null default '',href text not null default '',art text not null default '',media text not null default '',sort_order integer not null default 0,published boolean not null default false,updated_at timestamptz not null default now());
create table if not exists public.cinematic_films(id uuid primary key default gen_random_uuid(),slug text not null unique,title text not null,video_url text not null,note text not null default '',storyboard jsonb not null default '[]'::jsonb,sort_order integer not null default 0,published boolean not null default false,updated_at timestamptz not null default now());
create table if not exists public.project_bookings(id uuid primary key default gen_random_uuid(),name text not null check(char_length(name) between 1 and 120),email text not null check(char_length(email) between 3 and 254),service text not null check(char_length(service) between 1 and 120),notes text not null default '' check(char_length(notes)<=4000),timing text not null default '' check(char_length(timing)<=80),availability text not null default '' check(char_length(availability)<=80),status text not null default 'new' check(status in('new','reviewed','contacted','closed')),created_at timestamptz not null default now());
alter table public.site_content enable row level security; alter table public.portfolio_projects enable row level security; alter table public.cinematic_films enable row level security; alter table public.project_bookings enable row level security;
grant select on public.site_content,public.portfolio_projects,public.cinematic_films to anon,authenticated;
grant insert,update,delete on public.site_content,public.portfolio_projects,public.cinematic_films to authenticated;
grant insert on public.project_bookings to anon,authenticated; grant select,update on public.project_bookings to authenticated;
create policy "Public reads site content" on public.site_content for select to anon,authenticated using(true);
create policy "Site admin manages site content" on public.site_content for all to authenticated using(lower(coalesce((select auth.jwt()->>'email'),''))='sevenfold.ng@gmail.com') with check(lower(coalesce((select auth.jwt()->>'email'),''))='sevenfold.ng@gmail.com');
create policy "Public reads published projects" on public.portfolio_projects for select to anon,authenticated using(published=true or lower(coalesce((select auth.jwt()->>'email'),''))='sevenfold.ng@gmail.com');
create policy "Site admin manages projects" on public.portfolio_projects for all to authenticated using(lower(coalesce((select auth.jwt()->>'email'),''))='sevenfold.ng@gmail.com') with check(lower(coalesce((select auth.jwt()->>'email'),''))='sevenfold.ng@gmail.com');
create policy "Public reads published films" on public.cinematic_films for select to anon,authenticated using(published=true or lower(coalesce((select auth.jwt()->>'email'),''))='sevenfold.ng@gmail.com');
create policy "Site admin manages films" on public.cinematic_films for all to authenticated using(lower(coalesce((select auth.jwt()->>'email'),''))='sevenfold.ng@gmail.com') with check(lower(coalesce((select auth.jwt()->>'email'),''))='sevenfold.ng@gmail.com');
create policy "Visitors submit project bookings" on public.project_bookings for insert to anon,authenticated with check(true);
create policy "Site admin reads bookings" on public.project_bookings for select to authenticated using(lower(coalesce((select auth.jwt()->>'email'),''))='sevenfold.ng@gmail.com');
create policy "Site admin updates bookings" on public.project_bookings for update to authenticated using(lower(coalesce((select auth.jwt()->>'email'),''))='sevenfold.ng@gmail.com') with check(lower(coalesce((select auth.jwt()->>'email'),''))='sevenfold.ng@gmail.com');
